/** Actual registered item callbacks, Survival ownership, staged rollback, platform retention and restart. */
@EventBusSubscriber(modid="vandorlabs")
public final class GlassItemChecks {
 private static final BlockPos BASE=new BlockPos(7844,240,7844);private static NativeGlassBlock BLOCK;private static BlockEntityType<NativeGlassEntity> TYPE;private static FaultItem ITEM;private static int fault,checks,profiles;private static String context="";
 private static String phase(){return System.getProperty("vandorlabs.transmitterPhase","");}private static boolean enabled(){return phase().startsWith("flat-glass-item-");}private static void need(boolean yes,String text){checks++;if(!yes)throw new AssertionError("Glass item "+text+" "+context);}
 private static final class FaultItem extends NativeGlassItem {FaultItem(){super(BLOCK,new Item.Properties());}@Override protected boolean stage(net.minecraft.world.level.Level w,BlockPos p,BlockState s){boolean ok=super.stage(w,p,s);if(fault==1||fault==2)throw new IllegalStateException("Injected glass stage failure");if(fault==3)w.removeBlockEntity(p);return fault==4?false:ok;}@Override protected boolean restore(net.minecraft.world.level.Level w,BlockPos p,BlockState s){return fault==2?false:super.restore(w,p,s);}}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration{@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent e){if(!enabled())return;e.register(Registries.BLOCK,h->{BLOCK=new NativeGlassBlock(BlockBehaviour.Properties.of().strength(.5F,1.2F).sound(SoundType.GLASS),()->TYPE){@Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return fault==3?null:super.newBlockEntity(p,s);}};h.register(ResourceLocation.parse("vandorlabs:flat_glass_item_fixture"),BLOCK);});e.register(Registries.ITEM,h->{ITEM=new FaultItem();h.register(ResourceLocation.parse("vandorlabs:flat_glass_item_fixture"),ITEM);});e.register(Registries.BLOCK_ENTITY_TYPE,h->{TYPE=BlockEntityType.Builder.of((p,s)->new NativeGlassEntity(TYPE,p,s),BLOCK).build(null);h.register(ResourceLocation.parse("vandorlabs:flat_glass_item_fixture"),TYPE);});}}
 private static void source(ServerLevel w)throws Exception {int refused=0;try(var reader=Files.newBufferedReader(Path.of(System.getenv("VANDOR_FLAT_GLASS_ITEM_REFERENCE")))){for(String line;(line=reader.readLine())!=null;){var row=JsonParser.parseString(line).getAsJsonObject();context="Source profile="+profiles+" "+row.get("profile");var state=BLOCK.defaultBlockState().setValue(NativeGlassBlock.ROTATED,row.get("rotated").getAsInt()!=0).setValue(NativeGlassBlock.DEPTH,row.get("depth").getAsInt()).setValue(NativeGlassBlock.SIZE,row.get("size").getAsInt());String raw=row.get("outer").getAsString();var outer=raw.isEmpty()?null:TagParser.parseTag(raw);var base=row.get("generic").getAsInt()==0?null:TagParser.parseTag(row.get("base").getAsString());boolean failure=!row.get("failure").getAsString().isEmpty();try{var prepared=NativeGlassEntity.prepareItem(BLOCK,BASE,state,base,outer,(row.get("facing").getAsInt()+2)%4,w.registryAccess());need(!failure,"Source invalid layout must refuse");var owner=new NativeGlassEntity(TYPE,BASE,prepared.state);owner.loadWithComponents(prepared.snapshot,w.registryAccess());need(prepared.state.getValue(NativeGlassBlock.SIZE)==row.get("placedSize").getAsInt(),"Source raw state detail");var actual=new CompoundTag();owner.settings().write(actual);var wanted=new CompoundTag();NativeGlassSettings.read(TagParser.parseTag(row.get("saved").getAsString())).write(wanted);need(actual.equals(wanted),"Source full settings actual="+actual+" wanted="+wanted);var expectedPick=TagParser.parseTag(row.get("pick").getAsString()).getCompound("tag").getCompound(NativeGlassItem.CONFIGURATION);need(expectedPick.equals(NativeGlassItem.configuration(NativeGlassItem.pick(BLOCK,owner,prepared.state))),"Source configured pick tag actual="+NativeGlassItem.configuration(NativeGlassItem.pick(BLOCK,owner,prepared.state))+" wanted="+expectedPick);var drop=NativeGlassItem.drop(BLOCK,owner,prepared.state);need(drop.is(ITEM)&&drop.getCount()==1&&!drop.has(DataComponents.CUSTOM_DATA)&&!drop.has(DataComponents.BLOCK_ENTITY_DATA),"Source plain one-item drop");}catch(IllegalArgumentException invalid){if(!failure)throw invalid;refused++;}profiles++;}}
  need(profiles==3744&&refused==144,"actual Source callback coverage");
 }
 private static net.neoforged.neoforge.common.util.FakePlayer actor(ServerLevel w){var p=new net.neoforged.neoforge.common.util.FakePlayer(w,new com.mojang.authlib.GameProfile(UUID.fromString("68abae41-5585-4f76-9f23-6565d0bff32e"),"GlassItem"));p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.getInventory().selected=0;p.setYRot(Direction.SOUTH.toYRot());return p;}
 private static BlockPlaceContext placeContext(ServerLevel w,net.minecraft.server.level.ServerPlayer p,BlockPos pos,ItemStack stack){w.getChunkAt(pos);w.setBlock(pos.below(),Blocks.STONE.defaultBlockState(),18);p.setPos(pos.getX()+.5,pos.getY(),pos.getZ()-2);p.setItemInHand(InteractionHand.MAIN_HAND,stack);return new BlockPlaceContext(new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(new Vec3(pos.getX()+.375,pos.getY(),pos.getZ()+.625),Direction.UP,pos.below(),false)));}
 private static ItemStack stack(CompoundTag base,CompoundTag outer){var stack=new ItemStack(ITEM,2);var data=new CompoundTag();if(base!=null)data.put(NativeGlassItem.GENERIC,base.copy());if(outer!=null)data.put(NativeGlassItem.CONFIGURATION,outer.copy());if(!data.isEmpty())stack.set(DataComponents.CUSTOM_DATA,CustomData.of(data));return stack;}
 private static void write(ServerLevel w)throws Exception {
  source(w);context="actual player ownership";var actor=actor(w);var generic=new CompoundTag();generic.putString("FutureGlass","opaque:item");var caps=new CompoundTag();caps.putString("Owner","opaque:cap");generic.put("ForgeCaps",caps);var platform=new CompoundTag();platform.putString("Owner","platform:placed");generic.put("NeoForgeData",platform);generic.putInt("GlassShade",5);generic.putInt("FrameInterior",0);var outer=new CompoundTag();outer.putInt("Shade",99);outer.putInt("Tint",3);outer.putInt("Size",2);outer.putInt("LayoutMode",2);var held=stack(generic,outer);var ctx=placeContext(w,actor,BASE,held);need(ITEM.place(ctx).consumesAction()&&held.getCount()==1,"Survival placement consumes exactly one");var owner=(NativeGlassEntity)w.getBlockEntity(BASE);need(owner!=null&&!owner.inert()&&owner.settings().glass().shade==5&&owner.settings().glass().tint==3&&owner.settings().glass().size==1&&owner.getBlockState().getValue(NativeGlassBlock.SIZE)==2,"installed Source partial merge and raw detail");var saved=owner.saveWithoutMetadata(w.registryAccess());need(saved.getString("FutureGlass").equals("opaque:item")&&saved.getCompound("ForgeCaps").getString("Owner").equals("opaque:cap")&&saved.getCompound("NeoForgeData").getString("Owner").equals("platform:placed"),"prepared full snapshot installs opaque and live platform state");
  for(int mode=1;mode<=4;mode++){context="fault="+mode;BlockPos pos=BASE.east(mode*3);w.setBlock(pos,Blocks.AIR.defaultBlockState(),18);var input=stack(generic,outer);var before=input.copy();fault=mode;boolean threw=false;InteractionResult result=InteractionResult.FAIL;try{result=ITEM.place(placeContext(w,actor,pos,input));}catch(IllegalStateException expected){threw=true;}finally{fault=0;}if(mode==2){need(threw&&input.getCount()==1&&w.getBlockEntity(pos) instanceof NativeGlassEntity recovery&&recovery.inert(),"failed rollback retains exactly one inert owner");var recovery=(NativeGlassEntity)w.getBlockEntity(pos);need(recovery.recoverySnapshot().contains(NativeGlassEntity.PLACEMENT_RECOVERY),"retained placement recovery marker");var recovered=NativeGlassItem.pick(BLOCK,recovery,recovery.getBlockState());need(NativeGlassItem.configuration(recovered).contains(NativeGlassEntity.RECOVERY),"recovery pick preserves opaque payload");need(!ITEM.place(placeContext(w,actor,BASE.north(3),recovered)).consumesAction(),"recovery item refuses re-placement");}else need(w.getBlockState(pos).isAir()&&ItemStack.matches(before,input)&&(mode==1?threw:!result.consumesAction()),"failed stage restores old owner and inventory");}
  context="unsupported and mining";var invalid=outer.copy();invalid.putInt("LayoutMode",99);BlockPos badPos=BASE.south(3);w.setBlock(badPos,Blocks.AIR.defaultBlockState(),18);var invalidHeld=stack(generic,invalid);need(!ITEM.place(placeContext(w,actor,badPos,invalidHeld)).consumesAction()&&invalidHeld.getCount()==2&&w.getBlockState(badPos).isAir(),"invalid layout refuses before mutation");var future=generic.copy();future.putInt("NativeGlassSchema",99);var futureHeld=stack(future,null);need(!ITEM.place(placeContext(w,actor,badPos,futureHeld)).consumesAction()&&futureHeld.getCount()==2&&w.getBlockState(badPos).isAir(),"future owner refuses before mutation");
  BlockPos mined=BASE.south(6);var plain=stack(null,null);need(ITEM.place(placeContext(w,actor,mined,plain)).consumesAction(),"plain hand-harvest placement");actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);need(actor.gameMode.destroyBlock(mined)&&w.getBlockState(mined).isAir(),"real Survival hand harvest");var drops=w.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(mined).inflate(1));need(drops.size()==1&&drops.getFirst().getItem().is(ITEM)&&drops.getFirst().getItem().getCount()==1&&!drops.getFirst().getItem().has(DataComponents.CUSTOM_DATA),"exactly one plain Source hand drop");for(var drop:drops)drop.discard();w.setChunkForced(BASE.getX()>>4,BASE.getZ()>>4,true);w.setChunkForced((BASE.getX()+6)>>4,BASE.getZ()>>4,true);
 }
 private static void read(ServerLevel w){context="process restart";w.getChunkAt(BASE);var owner=(NativeGlassEntity)w.getBlockEntity(BASE);owner.refreshFluidGeometry();var saved=owner.saveWithoutMetadata(w.registryAccess());need(owner!=null&&!owner.inert()&&owner.settings().glass().shade==5&&owner.getBlockState().getValue(NativeGlassBlock.SIZE)==2&&saved.getString("FutureGlass").equals("opaque:item")&&saved.getCompound("NeoForgeData").getString("Owner").equals("platform:placed"),"valid item ownership restart");var recovery=(NativeGlassEntity)w.getBlockEntity(BASE.east(6));need(recovery!=null&&recovery.inert()&&recovery.recoverySnapshot().contains(NativeGlassEntity.PLACEMENT_RECOVERY),"failed rollback opaque ownership restart");}
 @SubscribeEvent public static void started(ServerStartedEvent e){if(!enabled())return;System.out.println("[vandorlabs][flat-glass-item] actual server PID="+ProcessHandle.current().pid());try{if(phase().endsWith("write"))write(e.getServer().overworld());else read(e.getServer().overworld());e.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][flat-glass-item] "+(phase().endsWith("write")?"write":"read")+" PASS checks="+checks+" SourceProfiles="+profiles);}catch(Throwable failure){System.err.println("[vandorlabs][flat-glass-item] FAIL "+failure);failure.printStackTrace();}finally{e.getServer().halt(false);}}
}
